#include <cassert>
#include <iostream>
#ifdef NDEBUG
#error Tests require assertions enabled
#endif
// 단일 구매 요청의 UI 상태를 검증하는 독창적 교육 모델.
enum class State { Idle, Pending, Success, Failure };
struct Request {
    State state=State::Idle;
    unsigned id=0;
    bool start(unsigned next) {
        if(state==State::Pending || next<=id) return false;
        id=next; state=State::Pending; return true;
    }
    bool complete(unsigned responseId, bool ok) {
        if(state!=State::Pending || responseId!=id) return false;
        state=ok?State::Success:State::Failure; return true;
    }
};
int main() {
    Request r;
    assert(r.start(1)); assert(!r.start(2));
    assert(!r.complete(0,true)); assert(r.state==State::Pending);
    assert(r.complete(1,false)); assert(!r.complete(1,true));
    assert(r.start(2)); assert(!r.complete(1,true));
    assert(r.complete(2,true)); assert(!r.start(2));
    for(unsigned i=3;i<10003;++i) {
        assert(r.start(i)); assert(!r.complete(i-1,true));
        assert(r.complete(i,i%2==0));
    }
    std::cout<<"response tests passed\n";
}
